// ---------- 1.1 ALPHABET A-Z ----------
function openAlphabetMenu(index = 0) {
    stopSpeaking();
    inAlphaIpaFlow = true;
    if (index < 0) index = 0;
    if (index >= ALPHABET_DATA.length) index = ALPHABET_DATA.length - 1;
    currentAlphabetIndex = index;
    updateNavTabs("1. Alphabet & IPA", "🔤", "Alphabet A-Z");
    switchAppView('view-alphabet');

    const item = ALPHABET_DATA[index];
    const keyboardHtml = ALPHABET_DATA.map((alpha, idx) => {
        const isActive = idx === currentAlphabetIndex;
        return `<button onclick="openAlphabetMenu(${idx})" class="ta2-az-keyboard-key pastel-btn flex flex-col items-center justify-center rounded-xl p-1.5 shadow-sm cursor-pointer ${isActive ? 'bg-pink-500 text-white border-2 border-pink-600 scale-105 ring-2 ring-pink-200' : 'bg-white text-gray-700 border border-gray-200 hover:bg-pink-50 hover:border-pink-300'} min-w-[52px] min-h-[52px]">
            <span class="text-xl font-black">${alpha.letter}</span>
            <span class="font-bold ${isActive ? 'text-white' : 'text-pink-600'} text-xl md:text-xl">${alpha.ipaName}</span>
        </button>`;
    }).join('');

    const wordCard = (w, idx) => `
        <div onclick="speakAlphaWord(${index},${idx})" class="ta2-az-word-card card-hover bg-white border-2 border-fuchsia-300 hover:border-fuchsia-500 rounded-xl p-2.5 flex flex-col items-center justify-center cursor-pointer shadow-sm">
            <div class="text-3xl mb-1">${w.emoji}</div>
            <div class="flex items-center gap-1"><span class="text-xl font-black text-violet-800">${escapeHtml(w.en)}</span><span class="text-xl px-1.5 py-0.2 rounded bg-fuchsia-100 text-fuchsia-700 font-bold">${w.pos || ''}</span></div>
            <div class="text-fuchsia-600 text-xl mt-0.5">${w.ipa}</div>
            <div class="text-xl font-extrabold text-gray-600 my-0.5">${escapeHtml(w.vi)}</div>
            <div class="text-xl font-bold text-gray-400 mb-1.5">"${escapeHtml(w.ex || '')}"</div>
            <span class="bg-fuchsia-50 text-fuchsia-700 border border-fuchsia-200 text-xl font-black px-2 py-0.5 rounded-lg">🔊 Listen</span>
        </div>`;

    document.getElementById('alphaipa-content').innerHTML = `
        <div class="ta2-alphabet-az w-full flex flex-col items-center">
            <div class="ta2-az-heading mb-2 text-center">
                <h2 class="text-xl md:text-xl font-black text-pink-600 mb-0.5">🔤 ENGLISH ALPHABET & PHONICS (A-Z)</h2>
                <p class="text-xl font-bold text-gray-500">Bấm vào chữ cái hoặc từ mẫu để nghe phát âm:</p>
                <button onclick="speakAlphabetLetter(${index})" class="pastel-btn mt-1.5 bg-pink-100 hover:bg-pink-200 text-pink-700 border border-pink-300 font-extrabold px-3.5 py-1 rounded-xl text-xl flex items-center justify-center gap-1 mx-auto shadow-sm cursor-pointer">
                    <i class="fa-solid fa-volume-high"></i><span>Listen to Letter ${item.letter}</span>
                </button>
            </div>
            <div class="ta2-az-word-grid bg-pink-50/60 border-2 border-dashed border-pink-300 rounded-2xl p-3 md:p-3.5 w-full mb-3 shadow-sm">
                <div class="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-4 gap-2.5 items-stretch">
                    <div onclick="speakAlphabetLetter(${index})" class="ta2-az-letter-card card-hover bg-white border-2 border-pink-400 rounded-xl p-3 flex flex-col items-center justify-center cursor-pointer shadow-sm bg-gradient-to-b from-white to-pink-50">
                        <div class="text-5xl md:text-6xl font-black text-pink-600 mb-1">${item.name}</div>
                        <div class="text-xl font-extrabold text-gray-600 mb-2">Cách đọc: <b class="text-purple-600 text-xl">${item.ipaName}</b></div>
                        <span class="bg-pink-100 text-pink-700 text-xl font-black px-2.5 py-0.5 rounded-full border border-pink-200">👆 Tap to Listen</span>
                    </div>
                    ${wordCard(item.word1, 1)}${wordCard(item.word2, 2)}${wordCard(item.word3, 3)}
                </div>
            </div>
            <div class="ta2-az-keyboard bg-white border border-gray-200 rounded-2xl p-2.5 w-full shadow-inner mb-2.5">
                <div class="flex flex-wrap items-center justify-center gap-1">${keyboardHtml}</div>
            </div>
            <div class="ta2-az-actions flex items-center justify-center space-x-3 mt-1">
                <button onclick="openAlphabetMenu(${index - 1})" class="pastel-btn bg-sky-50 hover:bg-sky-100 text-sky-600 border-2 border-sky-300 font-black text-xl md:text-xl px-4 py-2 rounded-xl shadow-sm flex items-center space-x-1 cursor-pointer ${index <= 0 ? 'opacity-40 pointer-events-none' : ''}"><i class="fa-solid fa-arrow-left"></i><span>Previous</span></button>
                <button onclick="openAlphabetPractice()" class="pastel-btn bg-violet-200 hover:bg-violet-300 text-violet-800 border-2 border-violet-300 font-black text-xl md:text-xl px-5 py-2 rounded-xl shadow-sm flex items-center gap-1.5 cursor-pointer"><span>🎯 Phonics Quiz</span></button>
                <button onclick="openAlphabetMenu(${index + 1})" class="pastel-btn bg-gradient-to-r from-pink-500 to-violet-500 hover:from-pink-600 hover:to-violet-600 text-white font-black text-xl md:text-xl px-5 py-2 rounded-xl shadow-sm flex items-center space-x-1 cursor-pointer ${index >= ALPHABET_DATA.length - 1 ? 'opacity-40 pointer-events-none' : ''}"><span>Next</span><i class="fa-solid fa-arrow-right"></i></button>
            </div>
        </div>`;
    speakAlphabetLetter(index);
}
function speakAlphabetLetter(index) { const item = ALPHABET_DATA[index]; if (item) speakEnglish(item.letter); }
function speakAlphaWord(index, wordNum) { const item = ALPHABET_DATA[index]; const w = item['word' + wordNum]; if (w) speakEnglish(w.en); }

// ---------- 1.2 IPA 44 SOUNDS ----------
function openIPAMenu(index = 0) {
    stopSpeaking();
    inAlphaIpaFlow = true;
    if (index < 0) index = 0;
    if (index >= IPA_DATA.length) index = IPA_DATA.length - 1;
    currentIPAIndex = index;
    updateNavTabs("1. Alphabet & IPA", "🔤", "Bảng ngữ âm IPA (44 âm)");
    switchAppView('view-alphabet');

    const item = IPA_DATA[currentIPAIndex];
    const soundButtonsHtml = IPA_DATA.map((snd, idx) => {
        const isActive = idx === currentIPAIndex;
        let badgeColor = isActive ? 'bg-pink-600 text-white border-pink-700' : 'bg-pink-50 text-pink-700 border-pink-200 hover:bg-pink-100';
        if (snd.type === 'vowel_di') badgeColor = isActive ? 'bg-purple-600 text-white border-purple-700' : 'bg-purple-50 text-purple-700 border-purple-200 hover:bg-purple-100';
        else if (snd.type && snd.type.startsWith('consonant')) badgeColor = isActive ? 'bg-fuchsia-600 text-white border-fuchsia-700' : 'bg-fuchsia-50 text-violet-700 border-fuchsia-200 hover:bg-fuchsia-100';
        return `<button onclick="openIPAMenu(${idx})" class="pastel-btn flex flex-col items-center justify-center rounded-xl p-1 shadow-sm border ${badgeColor} min-w-[50px] min-h-[46px] cursor-pointer ${isActive ? 'scale-105 ring-2 ring-pink-300 font-black' : ''}">
            <span class="text-xl md:text-xl font-black">${snd.ipa}</span>
            <span class="text-xl font-bold opacity-80 line-clamp-1">${(snd.name || '').split(' ')[0]}</span>
        </button>`;
    }).join('');

    const examplesHtml = (item.words || []).map((w, wIdx) => `
        <div onclick="speakIPAExampleWord(${currentIPAIndex},${wIdx})" class="card-hover bg-white border-2 border-fuchsia-300 hover:border-fuchsia-500 rounded-xl p-2.5 flex flex-col items-center justify-center cursor-pointer shadow-sm text-center">
            <div class="text-3xl mb-1">${w.emoji}</div>
            <div class="flex items-center gap-1"><span class="text-xl md:text-xl font-black text-violet-800">${escapeHtml(w.word)}</span><span class="text-xl px-1.5 py-0.2 rounded bg-fuchsia-100 text-fuchsia-700 font-bold">${w.pos || ''}</span></div>
            <div class="text-fuchsia-600 text-xl md:text-xl font-bold my-0.5">${w.ipa}</div>
            <div class="text-xl font-extrabold text-gray-700">${escapeHtml(w.vi)}</div>
            <div class="text-xl font-bold text-gray-400 mt-1 italic">"${escapeHtml(w.ex || '')}"</div>
            <span class="mt-1.5 bg-fuchsia-50 hover:bg-fuchsia-100 text-fuchsia-700 border border-fuchsia-200 text-xl font-black px-2.5 py-0.5 rounded-lg">🔊 Listen Word</span>
        </div>`).join('');

    let typeTag = 'Nguyên âm đơn (Monophthong)', typeBg = 'bg-pink-100 text-pink-700 border-pink-300';
    if (item.type === 'vowel_di') { typeTag = 'Nguyên âm đôi (Diphthong)'; typeBg = 'bg-purple-100 text-purple-700 border-purple-300'; }
    else if (item.type === 'consonant_unvoiced') { typeTag = 'Phụ âm vô thanh (Voiceless)'; typeBg = 'bg-violet-100 text-violet-700 border-violet-300'; }
    else if (item.type === 'consonant_voiced') { typeTag = 'Phụ âm hữu thanh (Voiced)'; typeBg = 'bg-fuchsia-100 text-fuchsia-700 border-fuchsia-300'; }

    document.getElementById('alphaipa-content').innerHTML = `
        <div class="w-full max-w-5xl flex flex-col items-center">
            <div class="mb-2 text-center w-full">
                <div class="flex items-center justify-between flex-wrap gap-1 mb-1">
                    <span class="text-xl font-black bg-pink-100 text-pink-700 px-3 py-1 rounded-xl shadow-sm">Âm ${currentIPAIndex + 1} / ${IPA_DATA.length} IPA</span>
                    <h2 class="text-xl md:text-xl font-black text-pink-600 flex items-center justify-center gap-1.5"><span>🗣️</span><span>BẢNG PHIÊN ÂM QUỐC TẾ IPA</span><span>🎙️</span></h2>
                    <button onclick="openIPAPractice()" class="pastel-btn bg-violet-200 hover:bg-violet-300 text-violet-800 border-2 border-violet-300 text-xl font-black px-3.5 py-1 rounded-xl shadow-sm flex items-center gap-1 cursor-pointer"><span>🎯 IPA Quiz</span></button>
                </div>
                <p class="text-xl font-bold text-gray-500">Bấm vào bất kỳ âm IPA nào để nghe phát âm chuẩn và xem hướng dẫn chi tiết:</p>
            </div>
            <div class="bg-gradient-to-r from-pink-50/80 via-fuchsia-50/80 to-violet-50/80 border-2 border-dashed border-pink-300 rounded-2xl p-3 md:p-4 w-full mb-3 shadow-sm">
                <div class="grid grid-cols-1 md:grid-cols-12 gap-3 items-stretch">
                    <div class="md:col-span-5 bg-white/95 rounded-2xl p-3 border border-pink-200 shadow-sm flex flex-col items-center justify-between text-center">
                        <div>
                            <span class="text-xl md:text-xl font-black uppercase px-2.5 py-0.5 rounded-full border ${typeBg} inline-block mb-1.5">${typeTag}</span>
                            <div onclick="speakIPASound(${currentIPAIndex})" class="cursor-pointer group">
                                <div class="text-5xl md:text-6xl font-black text-pink-600 drop-shadow-sm group-hover:scale-105 transition transform">${item.ipa}</div>
                                <div class="text-xl md:text-xl font-black text-purple-700 mt-1">${escapeHtml(item.name)}</div>
                            </div>
                        </div>
                        <div class="my-2.5 bg-gradient-to-br from-pink-50/80 to-violet-50/80 border border-violet-200 rounded-xl p-2.5 text-left w-full shadow-inner">
                            <div class="text-xl font-black text-violet-700 uppercase tracking-wide flex items-center gap-1 mb-1"><i class="fa-solid fa-lightbulb text-fuchsia-500"></i><span>Hướng dẫn phát âm chuẩn:</span></div>
                            <p class="text-xl font-bold text-gray-700 leading-relaxed">${escapeHtml(item.guide || '')}</p>
                        </div>
                        <div class="flex items-center justify-center gap-2 w-full mt-auto">
                            <button onclick="speakIPASound(${currentIPAIndex})" class="pastel-btn flex-1 bg-pink-500 hover:bg-pink-600 text-white font-black text-xl py-2 px-3 rounded-xl shadow-md flex items-center justify-center gap-1.5 cursor-pointer"><i class="fa-solid fa-volume-high"></i><span>Nghe âm ${item.ipa}</span></button>
                            <button onclick="speakIPAGuideVietnamese(${currentIPAIndex})" class="pastel-btn bg-purple-100 hover:bg-purple-200 text-purple-700 border border-purple-300 font-black text-xl py-2 px-2.5 rounded-xl shadow-sm flex items-center justify-center gap-1 cursor-pointer"><i class="fa-solid fa-language"></i><span>Đọc hướng dẫn</span></button>
                        </div>
                    </div>
                    <div class="md:col-span-7 flex flex-col justify-between">
                        <div class="text-left mb-1.5 flex items-center justify-between">
                            <span class="text-xl font-black text-violet-800 uppercase tracking-wider flex items-center gap-1"><i class="fa-solid fa-star text-fuchsia-400"></i><span>3 VÍ DỤ TỪ VỰNG CHUẨN CỦA ÂM ${item.ipa}:</span></span>
                        </div>
                        <div class="grid grid-cols-1 sm:grid-cols-3 gap-2 flex-1 items-stretch">${examplesHtml}</div>
                        <div class="mt-2 text-center text-xl font-bold text-gray-400">👆 Chạm vào từng thẻ để nghe phát âm từ vựng và câu ví dụ sinh động!</div>
                    </div>
                </div>
            </div>
            <div class="bg-white border border-gray-200 rounded-2xl p-2.5 w-full shadow-inner mb-2.5">
                <div class="flex flex-wrap items-center justify-center gap-1">${soundButtonsHtml}</div>
            </div>
            <div class="flex items-center justify-center space-x-3">
                <button onclick="openIPAMenu(${currentIPAIndex - 1})" class="pastel-btn bg-sky-50 hover:bg-sky-100 text-sky-600 border-2 border-sky-300 font-black text-xl px-5 py-2 rounded-xl shadow-sm flex items-center space-x-1.5 cursor-pointer ${currentIPAIndex <= 0 ? 'opacity-40 pointer-events-none' : ''}"><i class="fa-solid fa-arrow-left"></i><span>Previous Sound</span></button>
                <button onclick="openIPAMenu(${currentIPAIndex + 1})" class="pastel-btn bg-violet-200 hover:bg-violet-300 text-violet-800 border-2 border-violet-300 font-black text-xl px-6 py-2 rounded-xl shadow-md flex items-center space-x-1.5 cursor-pointer ${currentIPAIndex >= IPA_DATA.length - 1 ? 'opacity-40 pointer-events-none' : ''}"><span>Next Sound</span><i class="fa-solid fa-arrow-right"></i></button>
            </div>
        </div>`;
    speakIPASound(currentIPAIndex);
}
function speakIPASound(index) { const item = IPA_DATA[index]; if (item) speakEnglish(item.soundWord || item.ipa); }
function speakIPAGuideVietnamese(index) { const item = IPA_DATA[index]; if (item) speakVietnamese(item.guide || ''); }
function speakIPAExampleWord(index, wordIdx) { const item = IPA_DATA[index]; const w = item.words && item.words[wordIdx]; if (w) speakEnglish(w.word); }

// ---------- 1.3 ALPHABET PRACTICE + 1.4 IPA PRACTICE ----------
// Hai nhánh độc lập; không gộp câu theo topic_id 1 hoặc bắt bé học IPA trước.
function openAlphaIpaPracticeSection_(sectionCode, title) {
    stopSpeaking();
    showLoadingOverlay('Đang tải ' + title + '...');
    fetchAllQuestionsFlat().then(flat => {
        hideLoadingOverlay();
        const questions = flat.filter(q => q.sub_topic === sectionCode);
        const kinds = sectionCode === '1.3' ? new Set(['letter_listen','letter_name_ipa','letter_sequence']) : new Set(['ipa_sound']);
        if (!questions.length || questions.some(q => !kinds.has(q.phonics_kind))) {
            return taShowAlert('Dữ liệu mục ' + sectionCode + ' chưa đồng bộ. Anh/chị vui lòng tải lại phiên bản mới của chương trình nhé!');
        }
        activeTopicId = 1;
        pendingTopicQuiz = null; activeExamContext = null; activeRoadmapContext = null;
        practiceCycleRawPool = shuffleArray([...questions]);
        updateNavTabs('1. Alphabet & IPA', '🔤', sectionCode + ' ' + title);
        startTopicQuiz(1, sectionCode + ' ' + title, practiceCycleRawPool, sectionCode + ' ' + title);
    }).catch(() => {
        hideLoadingOverlay();
        taShowAlert('Chưa tải được bài luyện tập. Bé hãy thử lại nhé!');
    });
}
function openAlphabetPractice() { return openAlphaIpaPracticeSection_('1.3', 'Alphabet Practice'); }
function openIPAPractice() { return openAlphaIpaPracticeSection_('1.4', 'IPA Practice'); }

// ==========================================
// ĐIỀU HƯỚNG VIEW & BREADCRUMB
// ==========================================
let currentMainTab = 'discover';
let headerLevel2ClickHandler = null;
let headerLevel3ClickHandler = null;
let headerLevel4ClickHandler = null;

const MAIN_HEADER_PATH_ = {
    discover:  { title: 'Explore',    icon: '🧭' },
    lessons:   { title: 'Lessons',    icon: '📖' },
    exercises: { title: 'Exercises',  icon: '✏️' },
    review:    { title: 'Review',     icon: '🧠' },
    exams:     { title: 'Exams',      icon: '🏆' },
    games:     { title: 'Mini Games', icon: '🎮' }
};

function onHeaderLevel2Click() {
    if (typeof headerLevel2ClickHandler === 'function') headerLevel2ClickHandler();
}
function onHeaderLevel3Click() {
    if (typeof headerLevel3ClickHandler === 'function') headerLevel3ClickHandler();
}
function onHeaderLevel4Click() {
    if (typeof headerLevel4ClickHandler === 'function') headerLevel4ClickHandler();
}

function normalizeHeaderLabel_(value) {
    return String(value || '')
        .toLowerCase()
        .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
        .replace(/[^a-z0-9]+/g, ' ')
        .trim();
}

function isSameAsMainHeader_(tabName, value) {
    const n = normalizeHeaderLabel_(value);
    const aliases = {
        discover:  ['explore', 'kham pha'],
        lessons:   ['lessons', 'bai hoc'],
        exercises: ['exercises', 'bai tap', 'ban do tien trinh tuan', 'tien trinh tuan'],
        review:    ['review', 'on tap', '11 practice play', 'practice play'],
        exams:     ['exams', 'tests', 'de thi', '12 dau truong de thi', 'dau truong de thi'],
        games:     ['mini games', 'mini game', 'tro choi', 'trung tam mini game']
    };
    return (aliases[tabName] || []).some(a => n === a || n.endsWith(' ' + a));
}

/**
 * Header path chuẩn:
 * Home -> Main tab -> Module/section -> Item/detail.
 * Giữ API cũ updateNavTabs(...) để không phải sửa hàng loạt engine hiện tại.
 */
// Điều hướng phân tầng đồng bộ với Toán 2: một tab cho mỗi cấp.
// API cũ updateNavTabs(...) vẫn giữ để không thay toàn bộ engine của Tiếng Anh.
function englishBreadcrumbModuleHub_(title) {
    const t = String(title || '').trim();
    if (/^1\.\s*Alphabet\s*&\s*IPA/i.test(t)) return openAlphabetIPA;
    if (/^2\.\s*Vocabulary/i.test(t)) return openVocabularyHub;
    if (/^3\.\s*Remove Letter/i.test(t)) return () => openSharedVocabActivityHub_(3);
    if (/^4\.\s*Fill Missing/i.test(t)) return () => openSharedVocabActivityHub_(4);
    if (/^5\.\s*Odd One Out/i.test(t)) return openOddOneOutLevelHub_;
    if (/^(6\.\s*)?Reading Comprehension/i.test(t)) return openReadingComprehensionHub_;
    if (/^7\.\s*Sentence Builder/i.test(t)) return () => openExploreLevelHub_(7);
    if (/^8\.\s*Fill Sentence/i.test(t)) return () => openExploreLevelHub_(8);
    if (/^9\.\s*Q&A Dialogues/i.test(t)) return () => openExploreLevelHub_(9);
    if (/^11\.\s*Picture & Situation Challenge/i.test(t)) return openPictureSituationChallengeHub_;
    if (/^12\.\s*Super Vocabulary/i.test(t)) return openAdvancedVocabularyHub_;
    if (/^Super Vocabulary/i.test(t)) return openAdvancedVocabularyHub_;
    if (/^Situation Reading Challenge/i.test(t)) return openAdvancedSituationReadingHub_;
    if (/^Look at the Picture & Answer/i.test(t)) return openPictureQuestionReviewHub_;
    return null;
}

function englishBreadcrumbShortName_(text, type) {
    const value = String(text || '').trim();
    if (type === 'module') {
        if (/^11\.\s*Picture & Situation Challenge/i.test(value)) return '11. Picture & Situation';
        if (/^12\.\s*Super Vocabulary/i.test(value)) return '12. Super Vocabulary';
        if (/^Super Vocabulary(?:\s*\/|$)/i.test(value)) return 'Super Vocabulary';
        if (/^Situation Reading Challenge(?:\s*\/|$)/i.test(value)) return 'Reading Challenge';
        if (/^Look at the Picture & Answer(?:\s*\/|$)/i.test(value)) return 'Picture Questions';
    }
    if (type === 'review-branch') {
        if (/^Easy\s*\/\s*Dễ$/i.test(value)) return 'Easy';
        if (/^Medium\s*\/\s*Vừa$/i.test(value)) return 'Medium';
        if (/^Hard\s*\/\s*Khó$/i.test(value)) return 'Hard';
        // Riêng Siêu từ vựng: chỉ giữ tên chủ đề, không nhét bản dịch vào cùng tab.
        return value.split(/\s+\/\s+/)[0].trim();
    }
    return value;
}

function updateNavTabs(level2Title, level2Icon, level3Title, level4Title, level3ClickHandler) {
    const tabsRoot = document.getElementById('header-learning-tabs');
    if (!tabsRoot) return;
    tabsRoot.classList.remove('ta2-review-breadcrumb');
    tabsRoot.classList.add('ta2-math-style-breadcrumb');
    document.getElementById('app-context-banner')?.classList.remove('ta2-review-path-banner');
    const visible = Boolean(level2Title);
    const nodes = [2,3,4,5].map(level => ({
        level,
        wrap:document.getElementById(`header-level${level}-tab`),
        btn:document.getElementById(`header-level${level}-btn`),
        label:document.getElementById(`header-level${level}-title`)
    }));
    if (!visible) {
        nodes.forEach(node => {
            node.wrap?.classList.add('hidden');
            node.wrap?.classList.remove('flex');
        });
        return;
    }

    const mainKey = currentMainTab;
    const mainMeta = MAIN_HEADER_PATH_[mainKey] || MAIN_HEADER_PATH_.discover;
    const mainLabels = {
        discover:'Khám phá', lessons:'Bài học', exercises:'Bài tập',
        review:'Ôn tập', exams:'Đề thi', games:'Mini games'
    };
    const crumbs = [{
        text:mainLabels[mainKey] || mainMeta.title,
        full:mainLabels[mainKey] || mainMeta.title,
        icon:mainMeta.icon,
        go:() => openMainTab(mainKey)
    }];

    const sourceModule = String(level2Title || '').trim();
    const isVocabularyReview = mainKey === 'discover' && /^12\.\s*Super Vocabulary/i.test(sourceModule);
    const isReadingReview = mainKey === 'discover' && /^11\.\s*Picture & Situation Challenge/i.test(sourceModule)
        && /^Situation Reading Challenge/i.test(String(level3Title || ''));
    const isPictureReview = mainKey === 'discover' && /^11\.\s*Picture & Situation Challenge/i.test(sourceModule)
        && /^Look at the Picture & Answer/i.test(String(level3Title || ''));
    const nestedModule = !isSameAsMainHeader_(mainKey, sourceModule);
    if (nestedModule) {
        const moduleHub = englishBreadcrumbModuleHub_(sourceModule);
        crumbs.push({
            text:englishBreadcrumbShortName_(sourceModule, 'module'),
            full:sourceModule,
            go:moduleHub || returnToTopicLecture
        });
    }
    if (level3Title) {
        let back = null;
        if ((isReadingReview || isPictureReview) && level4Title && typeof level3ClickHandler === 'function') {
            back = level3ClickHandler; // Quay về đúng danh sách bài thuộc cấp độ.
        } else if (!isVocabularyReview && !isReadingReview && !isPictureReview && typeof level3ClickHandler === 'function') {
            back = level3ClickHandler;
        }
        // In Mini Games, clicking the game-name breadcrumb returns to that
        // game's own starting screen (not the overall Mini Games catalog).
        if (mainKey === 'games') {
            // Use the active game's stable ID; keep the title fallback for older callers.
            // Every one of the 12 game breadcrumbs goes back to its own start screen.
            const selectedGame = MINIGAME_LIST.find(game => game.id === taEnglishCurrentGameKey_)
                || MINIGAME_LIST.find(game => game.title === String(level3Title).trim());
            if (selectedGame) back = () => openGamePlay(selectedGame.id);
        }
        crumbs.push({
            text:englishBreadcrumbShortName_(level3Title, isVocabularyReview || isReadingReview || isPictureReview ? 'review-branch' : 'normal'),
            full:String(level3Title),
            go:back
        });
    }
    if (level4Title) crumbs.push({text:String(level4Title).trim(),full:String(level4Title),go:null});

    nodes.forEach((node, index) => {
        if (!node.wrap || !node.btn || !node.label) return;
        const crumb = crumbs[index];
        if (!crumb) {
            node.wrap.classList.add('hidden');
            node.wrap.classList.remove('flex');
            node.btn.onclick = null;
            node.btn.removeAttribute('aria-current');
            node.btn.removeAttribute('data-navigate');
            return;
        }
        const isLeaf = index === crumbs.length - 1;
        // Game names are the final breadcrumb but must remain clickable.
        const gameRootLink = isLeaf && mainKey === 'games' && index === 1;
        const canNavigate = typeof crumb.go === 'function' && (!isLeaf || gameRootLink);
        node.label.textContent = crumb.text;
        node.btn.title = crumb.full;
        node.btn.setAttribute('aria-label', canNavigate ? `Quay về ${crumb.full}` : crumb.full);
        node.btn.onclick = canNavigate ? () => {stopSpeaking();crumb.go();} : null;
        // The stylesheet targets [data-navigate="true"]; toggleAttribute() writes
        // an empty value, making a clickable game tab look inactive.
        if (canNavigate) node.btn.setAttribute('data-navigate', 'true');
        else node.btn.removeAttribute('data-navigate');
        if (isLeaf && !canNavigate) node.btn.setAttribute('aria-current','page');
        else node.btn.removeAttribute('aria-current');
        node.wrap.classList.remove('hidden');
        node.wrap.classList.add('flex');
    });
    const icon = document.getElementById('header-level2-icon');
    if (icon) icon.textContent = mainMeta.icon;
    document.getElementById('btn-header-home')?.classList.add('opacity-80', 'hover:opacity-100');
    // Tên dài không bị ellipsis; trên màn hẹp tự cuộn để luôn thấy cấp hiện tại.
    tabsRoot.scrollLeft = Math.max(0, tabsRoot.scrollWidth - tabsRoot.clientWidth);
}

function returnToTopicLecture() {
    stopSpeaking();
    clearInterval(quizTimerInterval);
    if (activeQuestionsList[currentQIndex]?.render_style === 'advanced_situation_reading' && activeAdvancedReadingLevel_) {
        return openAdvancedSituationReadingHub_();
    }
    if (activeQuestionsList[currentQIndex]?.render_style === 'picture_question_review' && activePictureQuestionReviewLevel_) {
        return openPictureQuestionReviewHub_();
    }

    // Các module Explore có hub riêng phải quay lại đúng hub của chính nó.
    // Không dùng fallback chung vì các module 2-9 không chia sẻ cùng một lecture state.
    const topicId = Number(activeTopicId);
    if (topicId === 1) return openAlphabetIPA();
    if (topicId === 2) return openVocabularyHub();
    if (topicId === 3 || topicId === 4) return openSharedVocabActivityHub_(topicId);
    if (topicId === 5) return openOddOneOutLevelHub_();
    if (topicId === 6) return openReadingComprehensionHub_();
    if (topicId === 7 || topicId === 8 || topicId === 9) return openExploreLevelHub_(topicId);

    if (activeExamContext) {
        openExamHub();
    } else if (activeRoadmapContext) {
        openRoadmap();
    } else if (pendingTopicQuiz) {
        // Render lại đúng danh sách mục nhỏ CẤP 1 (không phải màn chọn Nhóm Kép cấp 3 vừa hiện trước đó)
        showLectureAndSubtopics(pendingTopicQuiz.topicNum, pendingTopicQuiz.topicName, { questions: pendingTopicQuiz.questions });
    } else if (inAlphaIpaFlow) {
        // Đang duyệt Alphabet A-Z hoặc Bảng IPA (không phải quiz) -> quay về đúng menu 3 lựa chọn
        openAlphabetIPA();
    } else if (inMiniGameFlow) {
        // Đang ở Trung tâm Mini Game hoặc đang chơi 1 game cụ thể -> quay về lưới 12 game
        openMiniGameHub();
    }
}

function switchAppView(viewId) {
    ta2PracticeCancelSpeechTimer_();
    stopSpeaking();
    ['view-dashboard-grid', 'view-alphabet', 'view-lecture', 'view-quiz', 'view-roadmap', 'view-minigame-hub', 'view-game-play', 'view-exam-hub', 'view-result'].forEach(id => {
        const el = document.getElementById(id);
        if (!el) return;
        if (id === viewId) el.classList.remove('hidden');
        else el.classList.add('hidden');
    });
}

function goHome() {
    stopSpeaking();
    clearInterval(quizTimerInterval);
    inAlphaIpaFlow = false;
    inMiniGameFlow = false;
    activeVocabularyHubTopic = null;
    activeVocabularyStudyMode = 'flashcard';
    updateNavTabs(null, null, null);
    switchAppView('view-dashboard-grid');
}

function resetStars() {
    starGreenCount = 0; starRedCount = 0;
    const greenEl = document.getElementById('star-green-count');
    const redEl = document.getElementById('star-red-count');
    if (greenEl) greenEl.textContent = 0;
    if (redEl) redEl.textContent = 0;
}

function clickProgressOrExam(type) {
    if (type === 'progress') openRoadmap();
    else if (type === 'exam') openExamHub();
}


