// Lớp 2: bộ hẹn giờ dùng chung cho 12 mini game chạy trong module Tiếng Anh.
// Các file game gọi 2 hàm này; nếu thiếu, game dừng ngay khi vào vòng chơi.
const taEnglishGameTimeoutHandles_ = new Set();
const taEnglishGameIntervalHandles_ = new Set();
let taEnglishCurrentGameKey_ = null;
let taEnglishGameLoadEpoch_ = 0;
function taEnglishGameTimeout(callback, delay, ...args) {
    const handle = window.setTimeout(() => {
        taEnglishGameTimeoutHandles_.delete(handle);
        if (inMiniGameFlow && !document.getElementById('view-game-play')?.classList.contains('hidden')) {
            callback(...args);
        }
    }, Math.max(0, Number(delay) || 0));
    taEnglishGameTimeoutHandles_.add(handle);
    return handle;
}
function taEnglishGameInterval(callback, delay, ...args) {
    const handle = window.setInterval(() => {
        if (inMiniGameFlow && !document.getElementById('view-game-play')?.classList.contains('hidden')) {
            callback(...args);
        }
    }, Math.max(1, Number(delay) || 1000));
    taEnglishGameIntervalHandles_.add(handle);
    return handle;
}
function taEnglishStopCurrentGame_() {
    taEnglishGameLoadEpoch_++;
    if (taEnglishCurrentGameKey_) {
        try { taCurrentGameApi_?.stop?.(); } catch (_) {}
        removeTaGameHandlers_(taCurrentGameHandlers_); taCurrentGameApi_=null; taCurrentGameHandlers_=[];
    }
    for (const handle of taEnglishGameTimeoutHandles_) window.clearTimeout(handle);
    for (const handle of taEnglishGameIntervalHandles_) window.clearInterval(handle);
    taEnglishGameTimeoutHandles_.clear();
    taEnglishGameIntervalHandles_.clear();
    taEnglishCurrentGameKey_ = null;
}
