function buildReviewSemesterPools_(reviewQuestions) {
    const bySub = {};
    reviewQuestions.forEach(q => {
        const key = String(q.sub_topic || '').trim();
        if (!bySub[key]) bySub[key] = [];
        bySub[key].push(q);
    });
    return bySub;
}

function openSemesterReview_(subCode) {
    if (!requirePremiumAccess('Review / Ôn tập')) return;
    if (!pendingTopicQuiz?.reviewSemesterPools) return;
    const pool = pendingTopicQuiz.reviewSemesterPools[subCode] || [];
    if (!pool.length) return taShowAlert('Không tìm thấy dữ liệu ôn tập cho học kỳ này.');
    const label = subCode === '11.1' ? 'Semester 1 Review' : 'Semester 2 Review';
    practiceCycleRawPool = [...pool];
    updateNavTabs(label, '🧠', null);
    startTopicQuiz(11, label, shuffleArray([...pool]), subCode);
}

const EXPLORE_ADVANCED_11_TITLE_ = '11. Picture & Situation Challenge / Khám phá tranh và tình huống';
// Topic 11: each account/level owns a shuffled no-repeat learning deck.
// Only exercise ids and progress are stored; answers and account credentials are never stored.
const topic11DeckCache_ = Object.create(null);
function topic11DeckKey_(kind, level) {
    const uid = String(currentUser?.maHS || 'guest');
    let hash = 2166136261;
    for (let i = 0; i < uid.length; i++) { hash ^= uid.charCodeAt(i); hash = Math.imul(hash, 16777619); }
    return `ee_ta2_topic11_v2_${(hash >>> 0).toString(36)}_${kind}_${level}`;
}
function topic11Deck_(kind, level, pool) {
    const idField = kind === 'picture' ? 'picture_id' : 'reading_id';
    const ids = pool.map(item => String(item[idField] || ''));
    if (!ids.length || ids.some(id => !id) || new Set(ids).size !== ids.length) throw new Error('Kho bài Mục 11 thiếu mã định danh duy nhất.');
    const key = topic11DeckKey_(kind, level);
    const signature = [...ids].sort().join('|');
    let deck = topic11DeckCache_[key];
    if (!deck) {
        try { deck = JSON.parse(localStorage.getItem(key) || 'null'); } catch (_) { deck = null; }
    }
    const valid = deck && deck.signature === signature && Array.isArray(deck.order) &&
        deck.order.length === ids.length && new Set(deck.order).size === ids.length &&
        deck.order.every(id => ids.includes(id)) && Number.isInteger(deck.cursor) &&
        deck.cursor >= 0 && deck.cursor < ids.length;
    if (!valid) deck = {signature, order: shuffleArray([...ids]), cursor: 0, rounds: 0};
    topic11DeckCache_[key] = deck;
    try { localStorage.setItem(key, JSON.stringify(deck)); } catch (_) { /* Private mode: keep the in-memory deck. */ }
    return deck;
}
function topic11MarkCompleted_(kind, q) {
    const idField = kind === 'picture' ? 'picture_id' : 'reading_id';
    const level = q?.level;
    if (!['easy','medium','hard'].includes(level)) return;
    const deck = topic11Deck_(kind, level, activeQuestionsList);
    // Completing a previously visited lesson never advances the deck twice.
    if (deck.order[deck.cursor] !== String(q[idField])) return;
    deck.cursor++;
    if (deck.cursor >= deck.order.length) {
        const justFinishedId = String(q[idField]);
        deck.order = shuffleArray([...deck.order]);
        // Avoid an immediate repeat across two consecutive learning rounds.
        if (deck.order.length > 1 && deck.order[0] === justFinishedId) {
            const swap = 1 + Math.floor(Math.random() * (deck.order.length - 1));
            [deck.order[0],deck.order[swap]] = [deck.order[swap],deck.order[0]];
        }
        deck.cursor = 0;
        deck.rounds = (Number(deck.rounds) || 0) + 1;
        taModuleCtx_?.hooks?.showToast?.('🎉 Bé đã hoàn thành tất cả bài ở mức này! Vòng tiếp theo sẽ được xáo trộn mới.');
    }
    const key = topic11DeckKey_(kind,level);
    try { localStorage.setItem(key, JSON.stringify(deck)); } catch (_) { /* Session memory still works. */ }
}
function topic11Continue_(kind) {
    const current = activeQuestionsList[currentQIndex];
    if (!current) return;
    const idField = kind === 'picture' ? 'picture_id' : 'reading_id';
    const deck = topic11Deck_(kind, current.level, activeQuestionsList);
    const nextId = deck.order[deck.cursor];
    const nextIndex = activeQuestionsList.findIndex(row => String(row[idField]) === nextId);
    stopSpeaking();
    if (nextIndex > currentQIndex) { currentQIndex = nextIndex; loadQuestion(); return; }
    // A full cycle has ended; or a previous lesson was revisited.
    if (kind === 'picture') startPictureQuestionReviewLevel_(current.level);
    else startAdvancedSituationReadingLevel_(current.level);
}
async function startTopic11RandomLevel_(kind, level) {
    if (!['easy','medium','hard'].includes(level)) return;
    const isPicture = kind === 'picture';
    if (!requirePremiumAccess(isPicture ? 'Look at the Picture & Answer' : 'Situation Reading Challenge')) return;
    stopSpeaking();
    showLoadingOverlay('Đang xáo trộn câu hỏi...');
    try {
        const data = isPicture ? await loadPictureQuestionReviewData_() : await loadAdvancedSituationReadingData_();
        const pool = (isPicture ? data.pictures : data.readings).filter(row => row.level === level);
        const deck = topic11Deck_(kind, level, pool);
        const idField = isPicture ? 'picture_id' : 'reading_id';
        const byId = new Map(pool.map(row => [String(row[idField]),row]));
        const questions = deck.order.map(id => byId.get(id)).map(row => ({
            ...row, questions: shuffleArray([...row.questions]),
            render_style: isPicture ? 'picture_question_review' : 'advanced_situation_reading'
        }));
        activeVocabularyHubTopic = null;
        activeTopicId = 11; activeExamContext = null; activeRoadmapContext = null;
        pendingTopicQuiz = null; inMiniGameFlow = false; inAlphaIpaFlow = false;
        if (isPicture) {
            activePictureQuestionReviewLevel_ = level;
            pictureQuestionReviewState_ = Object.create(null);
        } else {
            activeAdvancedReadingLevel_ = level;
            advancedReadingState_ = Object.create(null);
        }
        const cfg = isPicture ? PICTURE_QUESTION_REVIEW_LEVELS_[level] : ADVANCED_SITUATION_READING_STYLES_[level];
        updateNavTabs(EXPLORE_ADVANCED_11_TITLE_,'🖼️',
            isPicture ? 'Look at the Picture & Answer' : 'Situation Reading Challenge',
            cfg.label, isPicture ? openPictureQuestionReviewHub_ : openAdvancedSituationReadingHub_);
        startTopicQuiz(11, (isPicture ? 'Look at the Picture' : 'Situation Reading') + ' · ' + cfg.label,
            questions, (isPicture ? 'picture-review-' : 'advanced-reading-') + level, deck.cursor);
    } catch (_) {
        const msg = 'Chưa thể mở câu hỏi Mục 11. Bé hãy thử tải lại trang nhé.';
        if (isPicture) pictureQuestionReviewNotice_(msg); else advancedSituationReadingNotice_(msg);
    } finally { hideLoadingOverlay(); }
}
function startPictureQuestionReviewLevel_(level) { return startTopic11RandomLevel_('picture',level); }
function startAdvancedSituationReadingLevel_(level) { return startTopic11RandomLevel_('reading',level); }

const EXPLORE_ADVANCED_12_TITLE_ = '12. Super Vocabulary / Siêu từ vựng nâng cao';
const exploreAdvancedJsonCache_ = Object.create(null);
async function loadExploreAdvancedJson_(topicId) {
    const id = Number(topicId);
    if (id !== 11 && id !== 12) throw new Error('Chuyên mục nâng cao không hợp lệ.');
    if (!exploreAdvancedJsonCache_[id]) {
        const path = `assets/data/english/kham_pha_tieng_anh_2_muc_${id}.json`;
        exploreAdvancedJsonCache_[id] = fetch(path, {cache:'default'}).then(response => {
            if (!response.ok) throw new Error('Không tải được học liệu nâng cao.');
            return response.json();
        }).then(data => {
            if (Number(data?.topic_id) !== id) throw new Error('Học liệu không khớp chuyên mục.');
            return data;
        }).catch(error => { delete exploreAdvancedJsonCache_[id]; throw error; });
    }
    return exploreAdvancedJsonCache_[id];
}
