        if (typeof taModuleCtx_!=='undefined' && taModuleCtx_?.hooks?.showToast) taModuleCtx_?.hooks?.showToast(notice);
        else if(typeof showFriendlyAlert==='function') showFriendlyAlert(notice,'📚');
