// ENGLISH 2 — ADVANCED SITUATION READING IN EXPLORE TOPIC 11
// 90 separate readings; independent of the basic Reading Comprehension module.
// Data is shared with picture questions in dedicated Muc 11 JSON.
const ADVANCED_SITUATION_READING_STYLES_ = {
    easy: {label:'Easy / Dễ',icon:'🌱',tone:'green',explain:'Đọc thông tin trực tiếp · 4 câu/bài'},
    medium:{label:'Medium / Vừa',icon:'🌼',tone:'blue',explain:'Kết nối tình huống và trình tự · 5 câu/bài'},
    hard:{label:'Hard / Khó',icon:'🌟',tone:'violet',explain:'Suy luận, giải thích và vận dụng · 6 câu/bài'}
};
function advancedSituationReadingNotice_(message) {
    if (typeof taModuleCtx_ !== 'undefined' && taModuleCtx_?.hooks?.showToast) {
        taModuleCtx_?.hooks?.showToast(String(message));
    } else {
        taShowAlert(String(message));
    }
}
async function loadAdvancedSituationReadingData_() {
    if (advancedReadingCache_) return advancedReadingCache_;
    const advancedData = await loadExploreAdvancedJson_(11);
    const data = advancedData?.advanced_situation_reading;
    if (!data) throw new Error('Chưa có dữ liệu Đọc hiểu nâng cao ở Mục 11.');
    const lessons = data?.readings;
    if (!Array.isArray(lessons) || lessons.length !== 90) throw new Error('Kho Đọc hiểu nâng cao chưa đủ 90 bài.');
    for(const level of ['easy','medium','hard']) {
        const group = lessons.filter(r=>r?.level===level);
        const expected = ADVANCED_SITUATION_READING_STYLES_[level];
        if (group.length !== 30 || group.some(r=>!Array.isArray(r.questions) || r.questions.length!==({easy:4,medium:5,hard:6}[level]))) {
            throw new Error(`Dữ liệu cấp ${expected.label} chưa hợp lệ.`);
        }
    }
    advancedReadingCache_ = data;
    return data;
}
function prepareAdvancedReadingLecture_(title) {
    resetLectureChrome_();
    hideReviewIntro_();
    const lectureInner = document.querySelector('#view-lecture > div:first-child');
    if (lectureInner) {lectureInner.classList.remove('max-w-4xl');lectureInner.classList.add('max-w-6xl');}
    const header = document.getElementById('lecture-title');
    if (header) header.textContent = title;
    setLectureSpeakVisible_(false);
    const mixWrap = document.getElementById('wrap-mix-all-subtopics');
    mixWrap?.classList.add('hidden');
}
