async function openAdvancedSituationReadingLevel_(level) {
    if (!Object.prototype.hasOwnProperty.call(ADVANCED_SITUATION_READING_STYLES_,level)) return;
    stopSpeaking();
    showLoadingOverlay('Đang chuẩn bị danh sách bài đọc...');
    try {
        const data=await loadAdvancedSituationReadingData_();
        const pool=data.readings.filter(r=>r.level===level).sort((a,b)=>Number(a.order)-Number(b.order));
        if(pool.length!==30)throw new Error('Kho bài đọc chưa đủ.');
        activeAdvancedReadingLevel_=level;
        const cfg=ADVANCED_SITUATION_READING_STYLES_[level];
        updateNavTabs(EXPLORE_ADVANCED_11_TITLE_, '🖼️', 'Situation Reading Challenge', cfg.label, openAdvancedSituationReadingHub_);
        prepareAdvancedReadingLecture_(`${cfg.icon} ${cfg.label} · 30 tình huống`);
        const list=document.getElementById('lecture-subtopics-list');
        if(!list)throw new Error('Thiếu vùng danh sách bài.');
        list.className='grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-2.5 w-full max-w-none px-0';
        const tones=['pink','violet','blue','amber','teal','green'];
        list.innerHTML=pool.map((r,idx)=>{
            const safeUrl=escapeHtml(r.image_url||'');
            const picture=safeUrl ? `<img src="${safeUrl}" alt="${escapeHtml(r.title_vi||'Tranh tình huống')}" loading="lazy" class="w-16 h-16 rounded-2xl object-contain bg-white border border-pink-100" onerror="this.style.display='none';">`:'<span class="text-4xl">📖</span>';
            return `<button type="button" onclick="openAdvancedSituationReadingLesson_('${level}',${idx})" class="ta2-hub-card ta2-hub-card--${tones[idx%6]} ta2-review-card text-left pastel-btn min-h-[108px]">
                    <span class="ta2-hub-top items-start">${picture}<span class="ta2-hub-head min-w-0"><span class="ta2-hub-number">${idx+1}. ${escapeHtml(r.title||'')}</span><span class="ta2-hub-topic-vi">${escapeHtml(r.title_vi||'')}</span><span class="block text-xl text-slate-500 font-extrabold mt-1">${Number(r.word_count||0)} từ · ${r.passage_type==='dialogue'?'💬 Hội thoại':'📄 Đoạn văn'}</span></span><span class="ta2-hub-card-chevron">›</span></span>
                </button>`;
        }).join('');
        switchAppView('view-lecture');
    }catch(_){advancedSituationReadingNotice_('Chưa thể tải danh sách bài đọc nâng cao.');}
    finally{hideLoadingOverlay();}
}
async function openAdvancedSituationReadingLesson_(level,index) {
    if (!requirePremiumAccess('Situation Reading Challenge / Đọc hiểu nâng cao')) return;
    if (!Object.prototype.hasOwnProperty.call(ADVANCED_SITUATION_READING_STYLES_,level)) return;
    const data=await loadAdvancedSituationReadingData_();
    const pool=data.readings.filter(r=>r.level===level).sort((a,b)=>Number(a.order)-Number(b.order));
    const at=Number(index);
    if (!Number.isInteger(at)||at<0||at>=pool.length)return;
    stopSpeaking();
    activeVocabularyHubTopic=null;
    activeAdvancedReadingLevel_=level;
    activeExamContext=null;
    activeRoadmapContext=null;
    activeTopicId=11;
    advancedReadingState_=Object.create(null);
    const cfg=ADVANCED_SITUATION_READING_STYLES_[level];
    updateNavTabs(EXPLORE_ADVANCED_11_TITLE_, '🖼️', 'Situation Reading Challenge',
                  `${cfg.label} · Bài ${at+1}`,()=>openAdvancedSituationReadingLevel_(level));
    startTopicQuiz(11,`Đọc hiểu tình huống · ${cfg.label}`,pool.map(r=>({...r,render_style:'advanced_situation_reading'})),`advanced-reading-${level}`);
    currentQIndex=at;
    loadQuestion();
}
function advancedReadingStateFor_(q) {
    const key=String(q.reading_id);
    if(!advancedReadingState_[key]) advancedReadingState_[key]={correct:Array(q.questions.length).fill(false),chosen:Array(q.questions.length).fill(-1),wrong:Array(q.questions.length).fill(false),wrongChoices:Array.from({length:q.questions.length},()=>[])};
    return advancedReadingState_[key];
}
function speakAdvancedSituationReading_() {
    const q=activeQuestionsList[currentQIndex];
    if(q?.render_style!=='advanced_situation_reading')return;
    speakEnglish(q.tts_text||q.passage||'',0.92);
}
function speakAdvancedSituationDialogueLine_(index) {
    const q=activeQuestionsList[currentQIndex];
    if(q?.render_style!=='advanced_situation_reading')return;
    const lines=String(q.passage||'').split('\n');
    const line=lines[Number(index)];
    if(typeof line==='string' && /^.{1,24}:\s/.test(line))speakEnglish(line.replace(/^.{1,24}:\s/,''),0.92);
}
function renderAdvancedSituationReading_(q) {
    if(!q || !Array.isArray(q.questions) || !q.questions.length)return;
    const state=advancedReadingStateFor_(q);
    const completed=state.correct.every(Boolean);
    const cfg=ADVANCED_SITUATION_READING_STYLES_[q.level]||ADVANCED_SITUATION_READING_STYLES_.easy;
    const dialog=q.passage_type==='dialogue';
    const lines=String(q.passage||'').split('\n');
    const passage=dialog?lines.map((line,i)=>{
        const m=line.match(/^([^:]{1,24}):\s*(.+)$/);
        if(!m)return `<p class="mb-2.5 text-xl md:text-xl text-slate-800 font-bold leading-relaxed">${escapeHtml(line)}</p>`;
        return `<div class="flex items-start gap-2 mb-2.5"><div class="w-10 shrink-0 rounded-xl bg-fuchsia-100 text-fuchsia-700 font-black text-center px-1 py-2 text-xl">${escapeHtml(m[1])}</div><div class="min-w-0 flex-1 rounded-2xl bg-white border border-pink-100 px-3 py-2 text-xl md:text-xl font-bold leading-relaxed text-slate-800">${escapeHtml(m[2])}</div><button type="button" onclick="speakAdvancedSituationDialogueLine_(${i})" class="shrink-0 text-violet-600 bg-violet-50 border border-violet-200 rounded-xl px-2 py-2 pastel-btn" aria-label="Listen to ${escapeHtml(m[1])}">🔊</button></div>`;
    }).join(''):`<p class="text-xl md:text-xl leading-[1.8] text-slate-800 font-bold">${escapeHtml(q.passage||'')}</p>`;
    const picture= q.image_url ? `<img src="${escapeHtml(q.image_url)}" alt="${escapeHtml(q.title_vi||q.title||'Reading picture')}" loading="lazy" class="w-full h-auto max-h-[270px] object-contain" onerror="this.style.display='none';const p=this.nextElementSibling;if(p)p.classList.remove('hidden')"><span class="hidden text-7xl">🖼️</span>` : '<span class="text-7xl">🖼️</span>';
    const qHtml=q.questions.map((item,qi)=>{
        const isRight=!!state.correct[qi];
        const hadWrong=!!state.wrong[qi];
        const choices=(item.options||[]).map((opt,oi)=>{
            const chose=Number(state.chosen[qi])===oi;
            const isCorrectChoice=isRight&&String(opt)===String(item.answer);
            const cls=isCorrectChoice?'border-emerald-400 bg-emerald-50 text-emerald-800':
                     (chose&&!isRight?'border-rose-400 bg-rose-50 text-rose-800':'border-pink-200 bg-white hover:bg-pink-50 text-slate-800');
            return `<button type="button" ${isRight?'disabled':''} onclick="answerAdvancedSituationReading_(${qi},${oi})" class="w-full text-left rounded-xl border-2 ${cls} px-3 py-2 text-xl md:text-xl font-bold leading-snug transition-all disabled:cursor-default"><span class="font-black text-fuchsia-500 mr-2">${String.fromCharCode(65+oi)}.</span>${escapeHtml(opt)}</button>`;
        }).join('');
        const translation=isRight&&item.question_vi?`<p class="text-xl text-slate-500 font-semibold mt-1">${escapeHtml(item.question_vi)}</p>`:'';
        const detail=isRight?`<p class="mt-2 rounded-xl border border-emerald-200 bg-emerald-50 p-2.5 text-xl md:text-xl font-semibold text-emerald-800">✅ ${escapeHtml(item.explanation||'Correct!')}</p>`:
                     hadWrong?`<p class="mt-2 rounded-xl border border-amber-200 bg-amber-50 p-2.5 text-xl md:text-xl font-semibold text-amber-800">💡 ${escapeHtml(item.hint_vi||'Hãy đọc lại đoạn văn để tìm gợi ý nhé.')}</p>`:'';
        const kind={detail:'Tìm thông tin',problem:'Nhận diện vấn đề',dialogue_reply:'Hiểu hội thoại',sequence:'Trình tự và giải pháp',inference:'Suy luận và vận dụng',true_false:'Đúng / Sai'}[item.question_kind]||'Đọc hiểu';
        return `<section class="rounded-2xl border border-pink-100 bg-white/90 p-3 shadow-sm"><div class="flex items-start gap-2 mb-2"><span class="w-7 h-7 shrink-0 rounded-full text-white bg-gradient-to-r from-pink-500 to-violet-500 font-black flex items-center justify-center text-xl">${qi+1}</span><div class="flex-1 min-w-0"><div class="text-xl text-violet-500 font-black mb-0.5">${kind}</div><h3 class="text-xl md:text-xl leading-snug font-extrabold text-slate-900">${escapeHtml(item.question||'')}</h3>${translation}</div></div><div class="grid grid-cols-1 sm:grid-cols-2 gap-2">${choices}</div>${detail}</section>`;
    }).join('');
    const meaning=completed&&q.passage_vi?`<div class="mt-3 p-3 rounded-2xl border border-violet-200 bg-white/90"><div class="text-violet-700 text-xl font-black mb-1">🇻🇳 Dịch nội dung sau khi hoàn thành</div><p class="text-slate-700 text-xl md:text-xl font-semibold leading-relaxed whitespace-pre-line">${escapeHtml(q.passage_vi)}</p></div>`:'';
    const host=document.getElementById('question-box');
    if(host)host.innerHTML=`<div class="ta2-advanced-reading-shell"><div class="flex items-center justify-between gap-2 mb-3 flex-wrap"><button type="button" onclick="openAdvancedSituationReadingHub_()" class="px-3 py-2 rounded-xl bg-white border border-pink-200 text-pink-700 text-xl font-extrabold pastel-btn">← Chọn mức độ</button><span class="px-3 py-1 rounded-full bg-rose-50 border border-rose-200 text-rose-700 text-xl md:text-xl font-black">${escapeHtml(cfg.icon)} ${escapeHtml(cfg.label)} · Bài ${currentQIndex+1} / ${activeQuestionsList.length} · ${q.word_count||0} từ</span><button type="button" onclick="speakAdvancedSituationReading_()" class="px-3 py-2 rounded-xl bg-violet-50 border border-violet-200 text-violet-700 text-xl font-black pastel-btn">🔊 Listen / Nghe toàn bài</button></div><div class="ta2-advanced-reading-layout"><section class="rounded-3xl border-2 border-pink-200 bg-gradient-to-br from-rose-50 via-white to-violet-50 p-3 md:p-4 text-left"><h2 class="text-xl md:text-2xl font-black text-fuchsia-700 mb-0.5">${escapeHtml(q.title||'')}</h2><p class="text-xl text-slate-500 font-bold mb-3">${escapeHtml(q.title_vi||'')} · ${dialog?'💬 Dialogue / Hội thoại':'📄 Story / Đoạn văn'}</p><div class="rounded-2xl border border-pink-100 bg-white/90 flex items-center justify-center p-2 mb-3 overflow-hidden min-h-[130px]">${picture}</div><div class="rounded-2xl bg-white/70 border border-rose-100 p-3">${passage}</div>${meaning}</section><div class="ta2-advanced-reading-questions">${qHtml}</div></div>${completed?'<div class="mt-3 text-center text-emerald-600 font-extrabold text-xl md:text-xl">🎉 Great job! Bé đã hiểu trọn vẹn tình huống này.</div>':''}</div>`;
    const prev=document.getElementById('btn-prev-q-prac');
    if(prev){prev.disabled=currentQIndex===0;prev.classList.toggle('opacity-40',currentQIndex===0);prev.classList.toggle('cursor-not-allowed',currentQIndex===0);}
    const next=document.getElementById('btn-next-q-prac');
    if(next){next.onclick=nextAdvancedSituationReading_;next.disabled=!completed;next.classList.toggle('opacity-40',!completed);next.classList.toggle('cursor-not-allowed',!completed);}
    const nextText=document.getElementById('btn-next-text-prac');
    if(nextText)nextText.textContent=currentQIndex===activeQuestionsList.length-1?'Hoàn thành':'Next';
}
// Section 11: quiz cards use custom answer handlers, so account for stars explicitly.
// The shared shell observes star-green-count/star-red-count and updates the header.
function topic11AwardStar_(isCorrect) {
    const key = isCorrect ? 'starGreenCount' : 'starRedCount';
    if (isCorrect) starGreenCount++; else starRedCount++;
    const el = document.getElementById(isCorrect ? 'star-green-count' : 'star-red-count');
    if (el) el.textContent = isCorrect ? starGreenCount : starRedCount;
    // Sync immediately, including when an older shell did not observe DOM mutations.
    if (typeof class2SyncLiveScore_ === 'function') class2SyncLiveScore_();
}
function answerAdvancedSituationReading_(questionIndex,optionIndex) {
    const q=activeQuestionsList[currentQIndex];
    if(!q||q.render_style!=='advanced_situation_reading')return;
    const qi=Number(questionIndex),oi=Number(optionIndex),item=q.questions[qi];
    if(!item||!Array.isArray(item.options)||!Number.isInteger(oi)||oi<0||oi>=item.options.length)return;
    const state=advancedReadingStateFor_(q);
    if(state.correct[qi])return;
    state.chosen[qi]=oi;
    if(String(item.options[oi])===String(item.answer)) {
        state.correct[qi]=true;
        topic11AwardStar_(true);
        playAudio('correct');
        if (state.correct.every(Boolean)) topic11MarkCompleted_('reading',q);
    }else{
        state.wrong[qi]=true;
        // Count an incorrect choice only once per question; allow trying other answers.
        const wrongChoices = state.wrongChoices[qi];
        if (!wrongChoices.includes(oi)) {
            wrongChoices.push(oi);
            topic11AwardStar_(false);
        }
        playAudio('wrong');
    }
    renderAdvancedSituationReading_(q);
}
function nextAdvancedSituationReading_() {
    const q=activeQuestionsList[currentQIndex];
    if(!q || q.render_style!=='advanced_situation_reading' || !advancedReadingStateFor_(q).correct.every(Boolean))return;
    topic11Continue_('reading');
}


// ===========================================================
// ENGLISH 2 — LOOK AT THE PICTURE & ANSWER (EXPLORE TOPIC 11)
// 3 independent observation questions x 4 options per catalog image.
// Data lives in dedicated Muc 11 JSON; image references are unchanged.
// ===========================================================
const PICTURE_QUESTION_REVIEW_TITLE_='Look at the Picture & Answer / Nhìn hình trả lời câu hỏi';
const PICTURE_QUESTION_REVIEW_LEVELS_={
    easy:{label:'Easy / Dễ',icon:'🌱',explain:'Quan sát sự vật và nhận biết thông tin rõ ràng'},
    medium:{label:'Medium / Vừa',icon:'🌼',explain:'Tìm chi tiết và kết nối thông tin trong tranh'},
    hard:{label:'Hard / Khó',icon:'🌟',explain:'Đọc kỹ tình huống, số lượng, vị trí và các chi tiết'}
};
const PICTURE_QUESTION_REVIEW_PAGE_SIZE_=12;
async function loadPictureQuestionReviewData_(){
    if(pictureQuestionReviewCache_)return pictureQuestionReviewCache_;
    const advancedData=await loadExploreAdvancedJson_(11);
    const data=advancedData?.picture_question_review;
    if(!data || !Array.isArray(data.pictures) || !data.pictures.length || data.pictures.length!==Number(data.picture_count))
        throw new Error('Kho bài Nhìn hình trả lời câu hỏi chưa đầy đủ.');
    const ids=new Set(),imageIds=new Set();
    for(const r of data.pictures){
        if(!Object.prototype.hasOwnProperty.call(PICTURE_QUESTION_REVIEW_LEVELS_,r.level)||
            !r.picture_id||ids.has(r.picture_id)||!r.image_id||imageIds.has(r.image_id)||
            !/^assets\/images\//.test(r.image_url||'')||!Array.isArray(r.questions)||r.questions.length!==3)
            throw new Error('Dữ liệu bài Nhìn hình không hợp lệ.');
        ids.add(r.picture_id);imageIds.add(r.image_id);
        for(const item of r.questions){
            if(!item.question_id||!item.question||!Array.isArray(item.options)||item.options.length!==4||
                new Set(item.options).size!==4||item.options.filter(s=>s===item.answer).length!==1)
                throw new Error('Câu hỏi Nhìn hình chưa đủ 4 lựa chọn rõ ràng.');
        }
    }
    pictureQuestionReviewCache_=data;
    return data;
}
function preparePictureQuestionReviewLecture_(title){
    resetLectureChrome_();hideReviewIntro_();
    const inner=document.querySelector('#view-lecture > div:first-child');
    if(inner){inner.classList.remove('max-w-4xl','max-w-6xl');inner.classList.add('ta2-review-lecture-full');}
    const header=document.getElementById('lecture-title');if(header)header.textContent=title;
    setLectureSpeakVisible_(false);
    document.getElementById('wrap-mix-all-subtopics')?.classList.add('hidden');
}
function pictureQuestionReviewNotice_(message){
    if(typeof taModuleCtx_!=='undefined' && taModuleCtx_?.hooks?.showToast)taModuleCtx_?.hooks?.showToast(message);
    else {const el=document.getElementById('lecture-title');if(el)el.textContent=message;}
}
