// Báo cáo 6 năng lực: không có dữ liệu không được hiểu là 0%.
function renderReportTopicsBreakdown(){
    const container=document.getElementById('report-topics-list');if(!container)return;const stats={};SKILL_KEYS.forEach(k=>stats[k]={total:0,correct:0,maxScore:0,earnedScore:0});activeQuestionsList.forEach((q,i)=>{let k=String(q.skill_tag||'ENG_VOC').toUpperCase();if(!SKILL_KEYS.includes(k))k='ENG_VOC';stats[k].total++;stats[k].maxScore+=(q.diem??0.5);if(userAnswers[i]===q.answer){stats[k].correct++;stats[k].earnedScore+=(q.diem??0.5);}});
    container.innerHTML=SKILL_KEYS.map(k=>{const d=stats[k];if(!d.total)return `<div class="bg-slate-50 border border-slate-200 rounded-2xl p-3"><div class="flex items-center justify-between gap-2"><span class="font-black text-slate-700 text-xl sm:text-xl">${SKILL_TAXONOMY[k].name}</span><span class="px-2.5 py-0.5 rounded-full bg-slate-100 text-slate-500 text-xl font-extrabold">Chưa đủ dữ liệu</span></div><div class="mt-2 text-xl font-bold text-slate-400">Bài này chưa có câu hỏi thuộc năng lực này.</div></div>`;const pct=Math.round(d.correct/d.total*100),pass=pct>=50;return `<div class="bg-pink-50/40 border border-pink-100 rounded-2xl p-3 space-y-2"><div class="flex items-center justify-between"><span class="font-black text-slate-800 text-xl sm:text-xl">${SKILL_TAXONOMY[k].name}</span><span class="px-2.5 py-0.5 rounded-full text-xl font-extrabold ${pass?'bg-violet-100 text-violet-700':'bg-rose-50 text-rose-700'}">${pass?'Đạt yêu cầu':'Cần luyện thêm'}</span></div><div class="flex justify-between text-xl font-bold text-slate-600"><span>Số câu đúng: <strong class="text-pink-600">${d.correct}/${d.total}</strong></span><span class="font-black">${pct}%</span></div><div class="w-full bg-pink-100 rounded-full h-2 overflow-hidden"><div class="${pass?'bg-gradient-to-r from-fuchsia-400 to-violet-400':'bg-gradient-to-r from-pink-400 to-rose-400'} h-full rounded-full" style="width:${pct}%"></div></div></div>`;}).join('');
}


function returnToTopicLecture(){
    stopSpeaking();clearInterval(quizTimerInterval);
    if(inBaiHocFlow){openBaiHocHub(activeBaiHocContext?.semester||1);return;}
    if(activeExamContext){openExamHub();return;}
    if(activeRoadmapContext){openRoadmap(activeRoadmapContext?.bai>8?2:1);return;}
    if(pendingTopicQuiz){showLectureAndSubtopics(pendingTopicQuiz.topicNum,pendingTopicQuiz.topicName,{questions:pendingTopicQuiz.questions});return;}
    if(inAlphaIpaFlow){openAlphabetIPA();return;}
    if(inMiniGameFlow){openMiniGameHub();return;}
    goHome();
}
const class2SkillSet = new Set(['ENG_PHO','ENG_VOC','ENG_LIS','ENG_GRA','ENG_SYN','ENG_READ']);
let class2ExerciseProgress = {unlockedIndex:1};
