// Live correct/wrong star totals to Class 2 shell.
// The assessment result remains server-verified until a NEW star event occurs.
let class2ScoreObserver_ = null;
let class2VerifiedScore_ = null;
let class2VerifiedScoreSnapshot_ = '';
function class2SyncLiveScore_() {
 if (!class2Active || !taModuleCtx_) return;
 const snapshot = String(starGreenCount) + ':' + String(starRedCount);
 if (class2VerifiedScore_ && snapshot !== class2VerifiedScoreSnapshot_) {
  class2VerifiedScore_ = null;
 }
 const right = class2VerifiedScore_ ? class2VerifiedScore_[0] : starGreenCount;
 const wrong = class2VerifiedScore_ ? class2VerifiedScore_[1] : starRedCount;
 taModuleCtx_?.hooks?.setScore(Math.max(0, Number(right) || 0), Math.max(0, Number(wrong) || 0));
}
function class2InstallScoreObserver_() {
 class2ScoreObserver_?.disconnect();
 const right = document.getElementById('star-green-count');
 const wrong = document.getElementById('star-red-count');
 if (!right || !wrong || !taModuleCtx_) return;
 class2ScoreObserver_ = new MutationObserver(class2SyncLiveScore_);
 for (const node of [right, wrong]) {
  class2ScoreObserver_.observe(node, {childList:true, characterData:true, subtree:true});
 }
 class2SyncLiveScore_();
}
const class2OriginalResetStars_ = resetStars;
resetStars = function() {
 class2VerifiedScore_ = null;
 const result = class2OriginalResetStars_.apply(this, arguments);
 class2SyncLiveScore_();
 return result;
};
