const class2OriginalNormalizeQuestion = normalizeQuestion;
normalizeQuestion=function(q){
 const x=class2OriginalNormalizeQuestion(q);
 if(!x)return x;
 x.question_type=q.question_type||'choice';
 x.activity_type=q.activity_type||'';
 x.answer_mode=q.answer_mode||'';
 x.tokens=Array.isArray(q.tokens)?q.tokens.slice():null;
 x.audio_only=!!q.audio_only;
 x.accepted_answers=Array.isArray(q.accepted_answers)?q.accepted_answers:null;
 x.visual_ref=q.visual_ref||null;
 x.image_id=q.image_id||q.visual_ref?.image_id||'';
 x.sub_code=q.sub_code||q.sub_topic||'';
 x.question_id=String(q.question_id||q.id||'');
 x.diem=Number(q.points??q.diem??q.score??0.5);
 return x;
};
