// Adaptive learning telemetry: original activity widgets stay unchanged.
// Each practice question contributes only its first attempt. Private writes use
// authenticated shell API and are scoped to subjectId=ta, never old TA2 tokens.
const class2Events=[];
const class2SeenAnswers=new Set();
let class2EventTimer=0;
let class2ActiveGame='';
function class2FlushEvents_(){
 if(class2EventTimer){clearTimeout(class2EventTimer);class2EventTimer=0;}
 if(!taModuleUser_().isAuthenticated||!class2Events.length)return;
 const events=class2Events.splice(0,20);
 taScopedApiRequest_('learningProfileSaveBatch',{subjectId:'ta',events}).catch(()=>{
  if(class2Active){class2Events.unshift(...events);if(class2Events.length>40)class2Events.splice(40);}
 });
}
function class2QueueEvent_(q,skill,result,activity){
 if(!taModuleUser_().isAuthenticated||!class2Active||!skill)return;
 class2Events.push({t:Date.now(),q:String(q||'').slice(0,64),s:String(skill).slice(0,72),o:result,e:String(activity||'practice').slice(0,48),u:0,l:0,tp:0});
 if(class2Events.length>=15){class2FlushEvents_();return;}
 if(!class2EventTimer)class2EventTimer=setTimeout(class2FlushEvents_,5000);
}
const class2OriginalCheckAnswer=checkAnswer;
checkAnswer=function(choice){
 const idx=currentQIndex,q=activeQuestionsList[idx],practice=!activeExamContext&&!activeRoadmapContext;
 const key=String(q?.question_id||'')+'@'+idx;
 const shouldTrack=practice&&q&&class2SkillSet.has(q.skill_tag)&&!class2SeenAnswers.has(key);
 const isRight=String(choice||'').trim().toLowerCase()===String(q?.answer||'').trim().toLowerCase();
 const out=class2OriginalCheckAnswer(choice);
 if(shouldTrack){class2SeenAnswers.add(key);class2QueueEvent_(q.question_id,q.skill_tag,isRight?'c':'w',q.sub_code||'explore');}
 return out;
};
