// New question types need their proper interactions; the old standalone engine
// handled its own legacy banks, but 2026 canonical exercises include fill_text/reorder_words.
const class2OriginalLoadQuestion=loadQuestion;
const class2OrderedTokens=new Map();
function class2BuildReorderAnswer_(ids,q){
 return ids.map(i=>String(q.tokens[i])).join(' ').replace(/\s+([.,!?])/g,'$1').trim();
}
function class2SetAnswer_(v){userAnswers[currentQIndex]=String(v||'').trim();updateQuizPalletUI();}
function class2ReorderTap_(index){
 const q=activeQuestionsList[currentQIndex];if(!q||!Array.isArray(q.tokens))return;
 const picks=class2OrderedTokens.get(currentQIndex)||[];
 if(!picks.includes(index))picks.push(index);
 class2OrderedTokens.set(currentQIndex,picks);class2SetAnswer_(class2BuildReorderAnswer_(picks,q));
 loadQuestion();
}
function class2ReorderUndo_(){
 const q=activeQuestionsList[currentQIndex];if(!q)return;
 const picks=class2OrderedTokens.get(currentQIndex)||[];picks.pop();
 class2OrderedTokens.set(currentQIndex,picks);const v=class2BuildReorderAnswer_(picks,q);
 if(v)class2SetAnswer_(v);else delete userAnswers[currentQIndex];loadQuestion();
}
function class2ReorderReset_(){class2OrderedTokens.set(currentQIndex,[]);delete userAnswers[currentQIndex];loadQuestion();}
function class2FillInput_(value){class2SetAnswer_(value);}
loadQuestion=function(){
 const q=activeQuestionsList[currentQIndex];
 const special=!!activeRoadmapContext && (q?.question_type==='fill_text'||q?.question_type==='reorder_words');
 if(!special){
  if(activeRoadmapContext&&q?.audio_only){const image=q.image_url,emoji=q.emoji;q.image_url='';q.emoji='';
   try{return class2OriginalLoadQuestion();}finally{q.image_url=image;q.emoji=emoji;}}
  return class2OriginalLoadQuestion();
 }
 stopSpeaking();
 const t=document.getElementById('q-badge-index');if(t)t.textContent=`CÂU ${currentQIndex+1} / ${activeQuestionsList.length}`;
 const skill=document.getElementById('q-skill-text');if(skill)skill.textContent=SKILL_TAXONOMY[q.skill_tag]?.name||'Bài tập Tiếng Anh 2';
 const pt=document.getElementById('q-badge-score');pt?.classList.add('hidden');
 const input=q.question_type==='fill_text'
   ? `<label class="block text-xl font-extrabold text-purple-700 mt-4">Write the full word · Viết từ hoàn chỉnh</label><input id="class2-fill-answer" type="text" autocomplete="off" spellcheck="false" maxlength="240" class="w-full mt-2 px-4 py-3 bg-white rounded-2xl border-2 border-purple-200 text-xl font-extrabold text-purple-800 focus:outline-none focus:border-pink-500" value="${escapeHtml(userAnswers[currentQIndex]||'')}">`
   : (()=>{const picks=class2OrderedTokens.get(currentQIndex)||[],selected=new Set(picks);
       return `<div class="rounded-2xl p-3 bg-pink-50 border-2 border-pink-200 min-h-[64px] text-xl font-black text-purple-700">${picks.length?escapeHtml(class2BuildReorderAnswer_(picks,q)):'Tap each word in the correct order'}</div>
       <div class="flex flex-wrap justify-center gap-2 mt-3">${q.tokens.map((word,i)=>`<button ${selected.has(i)?'disabled':''} onclick="class2ReorderTap_(${i})" class="px-4 py-3 bg-white border-2 border-purple-200 text-purple-700 font-black rounded-2xl ${selected.has(i)?'opacity-40':''}">${escapeHtml(word)}</button>`).join('')}</div>
       <div class="flex justify-center gap-2 mt-3"><button onclick="class2ReorderUndo_()" class="px-4 py-2 rounded-xl border border-purple-200 bg-white font-black text-purple-700">↶ Undo</button><button onclick="class2ReorderReset_()" class="px-4 py-2 rounded-xl border border-pink-200 bg-white font-black text-pink-600">↺ Reset</button></div>`})()
 const host=document.getElementById('question-box');
 if(host)host.innerHTML=`<div class="w-full max-w-3xl mx-auto p-3 md:p-5 rounded-3xl bg-gradient-to-br from-white via-pink-50 to-purple-50 border-2 border-pink-200 text-center">
    <div class="text-xl md:text-2xl font-black text-purple-700">${escapeHtml(q.question_text||'')}</div>
    <p class="text-xl font-bold text-slate-500 mt-2">${escapeHtml(q.question_text_vi||'')}</p>
    ${input}</div>`;
 const inputElement=document.getElementById('class2-fill-answer');
 inputElement?.addEventListener('input',ev=>class2FillInput_(ev.target.value));
 updateNavButtons();updateQuizPalletUI();
};
