// Existing result screen & educational correction design stays; submitting is server verified.
const class2OriginalShowResult = showResultScreen;


showResultScreen=async function(){
 if(class2AssessmentSubmitting || !taRuntimeAlive_)return;
 const official=!!activeRoadmapContext||!!activeExamContext;
 if(!official)return class2OriginalShowResult();
 if(!taModuleUser_().isAuthenticated){taModuleCtx_?.openAuth('login');return;}
 if(userAnswers==null||activeQuestionsList.some((_,i)=>String(userAnswers[i]??'').trim()==='')){
  taShowAlert('Con hãy hoàn thành tất cả câu hỏi trước khi nộp bài nhé!');return;
 }
 const exercise=!!activeRoadmapContext;class2AssessmentSubmitting=true;
 const submittingQuestions=activeQuestionsList;
 const submittingRoadmap=activeRoadmapContext, submittingExam=activeExamContext;
 showLoadingOverlay('Đang gửi bài để máy chủ xác minh...');
 try{
  const payload={subjectId:'ta',kind:exercise?'baitap':'baithi',
   answers:activeQuestionsList.map((q,i)=>({questionId:String(q.question_id),answer:String(userAnswers[i])})),
   durationMs:Math.min(14400000,Math.max(0,Date.now()-(quizStartTime||Date.now())))};
  if(exercise){payload.baiSo=Number(activeRoadmapContext.bai);payload.semester=payload.baiSo<=8?'hk1':'hk2';}
  else {const ctxExam=activeExamContext;
   payload.examId=ctxExam.examId||'';
   if(ctxExam.categoryKey==='hocky1')payload.semester='hk1';
   if(ctxExam.categoryKey==='hocky2')payload.semester='hk2';}
  const result=await taScopedApiRequest_('assessmentAttemptSubmit',payload);
  // The server can finish saving after the pupil leaves this quiz. Do not reopen it.
  if(!class2Active || activeQuestionsList!==submittingQuestions ||
     activeRoadmapContext!==submittingRoadmap || activeExamContext!==submittingExam ||
     document.getElementById('view-quiz')?.classList.contains('hidden'))return;
  for(let i=0;i<activeQuestionsList.length;i++){const q=activeQuestionsList[i];
   if(String(userAnswers[i]??'').normalize('NFC').replace(/\s+/g,' ').trim().toLowerCase()===String(q.answer??'').normalize('NFC').replace(/\s+/g,' ').trim().toLowerCase())userAnswers[i]=q.answer;}
  class2OriginalShowResult();
  const verifiedScore=document.getElementById('report-total-score-val');
  if(verifiedScore)verifiedScore.textContent=String(result.score!=null?result.score:(Number(result.correct||0)*10/Math.max(1,Number(result.total||1))).toFixed(1));
  const verifiedRatio=document.getElementById('report-correct-ratio-val');
  if(verifiedRatio)verifiedRatio.textContent=String(result.correct)+'/'+String(result.total);
  const receipt=document.getElementById('report-meta-display');
  if(receipt){receipt.textContent += result.saved===false?' · HSG không lưu lịch sử':' · ✅ Máy chủ đã xác minh và lưu điểm';}
  if(exercise){class2ExerciseProgress=result.progress||class2ExerciseProgress;
   if(result.passed===true)taModuleCtx_?.hooks?.showToast('🎉 Đạt từ 80%! Bài tập tiếp theo đã được mở khóa.');}
  class2VerifiedScore_ = [Math.max(0, Number(result.correct) || 0), Math.max(0, (Number(result.total) || 0) - (Number(result.correct) || 0))];
  class2VerifiedScoreSnapshot_ = String(starGreenCount) + ':' + String(starRedCount);
  class2SyncLiveScore_();
 }catch(_){taModuleCtx_?.hooks?.showToast('Chưa lưu được kết quả. Bé thử nộp lại nhé!');}
 finally{class2AssessmentSubmitting=false;hideLoadingOverlay();}
};
