// Official competency displays: missing sample is not zero; a single item is insufficient.
const class2OriginalReport=renderReportTopicsBreakdown;
renderReportTopicsBreakdown=function(){
 class2OriginalReport();
 const el=document.getElementById('report-topics-list');if(!el)return;
 // Original report keeps full layout; replace unsupported 1-item percentages with neutral evidence labels.
 const stats={};for(const k of class2SkillSet)stats[k]=0;
 for(const q of activeQuestionsList){if(class2SkillSet.has(q.skill_tag))stats[q.skill_tag]++;}
 for(const [i,k] of [...class2SkillSet].entries()){
  if(stats[k]>=2)continue;
  const box=el.children[i];if(!box)continue;
  const labels=box.querySelectorAll('span');
  if(!stats[k]){if(labels.length)labels[labels.length-1].textContent='Chưa đánh giá';}
  else {box.querySelectorAll('.bg-gradient-to-r').forEach(bar=>bar.style.width='0%');
   if(labels.length)labels[labels.length-1].textContent='Chưa đủ dữ liệu';}
 }
};
// History UI uses new verified rows; no default fabricated birth date or class information.
openHistoryModal=async function(sheetName='LichSuTienTrinhTuan'){
 if(!taModuleUser_().isAuthenticated){taModuleCtx_?.openAuth('login');return;}
 const kind=sheetName==='LichSuTienTrinhTuan'?'baitap':'baithi';
 const sem=sheetName==='LichSuBaiThiHK2'?'hk2':'hk1';
 if(sheetName==='LichSuBaiThiHSG')return taModuleCtx_?.hooks?.showToast('Đề HSG chưa có lịch sử riêng.');
 try{
  const resp=await taScopedApiRequest_('assessmentHistoryGet',{subjectId:'ta',kind,semester:sem});
  const rows=resp.history||[];
  const modal=document.getElementById('modal-history-progress');modal?.classList.remove('hidden');
  const name=document.getElementById('hist-info-name');if(name)name.textContent=currentUser.hoTen;
  const id=document.getElementById('hist-info-code');if(id)id.textContent=currentUser.maHS;
  const cl=document.getElementById('hist-info-class');if(cl)cl.textContent='Lớp 2';
  const dob=document.getElementById('hist-info-dob');if(dob)dob.textContent='Không thu thập';
  const title=document.getElementById('hist-modal-title');if(title)title.textContent=kind==='baitap'?'Lịch sử Bài tập':'Lịch sử Đề thi';
  renderHistoryReport(rows.map(r=>({
   ...r,ThoiGianGhi:r.Timestamp,deSo:r.DeSo,tuan:r.BaiSo,
   score:r.DiemSo||((Number(r.PhanTram||0)/10).toFixed(1)),tongDiem:r.DiemSo,
   tongCauHoi:r.TongCauHoi,soCauDung:r.SoCauDung,
   ...Object.fromEntries([...class2SkillSet].flatMap(k=>[[SKILL_TAXONOMY[k].sheetCol,r[k+'_Dung']||''],[SKILL_TAXONOMY[k].totalCol,r[k+'_Tong']||'']]))
  })),sheetName);
 }catch(_){taModuleCtx_?.hooks?.showToast('Chưa tải được lịch sử, con thử lại nhé.');}
};
// The original educational engine is preserved in this isolated module closure.
// Parent shell has its own header/navigation; child forwards detail and adjusts its height.
// Uniform folder/menu cards for the 6 English tabs and their submenus.
// Only the menu containers are observed; no quiz answer or lesson content is changed.
const ta2MenuTones_=['pink','violet','blue','amber','green','teal'];
function ta2MenuTone_(btn,index){
 const value=String(btn.className||'');
 for(const [regex,tone] of [
  [/\b(?:bg|border|text)-(?:pink|rose)-/, 'pink'],
  [/\b(?:bg|border|text)-(?:violet|purple|fuchsia)-/, 'violet'],
  [/\b(?:bg|border|text)-(?:blue|sky|indigo)-/, 'blue'],
  [/\b(?:bg|border|text)-(?:amber|orange|yellow)-/, 'amber'],
  [/\b(?:bg|border|text)-(?:green|emerald|lime)-/, 'green'],
  [/\b(?:bg|border|text)-(?:teal|cyan)-/, 'teal']
 ]) if(regex.test(value))return tone;
 return ta2MenuTones_[index%ta2MenuTones_.length];
}
function ta2TakeMenuEmoji_(btn){
 const title=btn.querySelector('.font-black,.font-extrabold,.ta2-hub-number,h3')||btn;
 const walker=document.createTreeWalker(title,NodeFilter.SHOW_TEXT);
 const pattern=/^\s*([\p{Extended_Pictographic}\p{Regional_Indicator}](?:[\p{Extended_Pictographic}\p{Regional_Indicator}\p{Emoji_Modifier}\uFE0E\uFE0F\u200D])*)(?:\s+|$)/u;
 let n,inspected=0;
 while((n=walker.nextNode())&&inspected++<10){
  const found=String(n.nodeValue||'').match(pattern);
  if(found){n.nodeValue=String(n.nodeValue).slice(found[0].length);return found[1];}
 }
 return '';
}
function ta2MenuIconFor_(label,index){
 const text=String(label||'').toLocaleLowerCase('vi');
 const icons=[
  [/alphabet|bảng chữ cái|letter|phonics|ipa|ngữ âm/,'🔤'],
  [/speak|pronunci|phát âm|nói/,'🎤'],
  [/listen|nghe/,'🎧'],
  [/flashcard|vocabulary|từ vựng|word bank/,'📚'],
  [/picture|hình|tranh|look at/,'🖼️'],
  [/reading|đọc|story|passage|đoạn văn|truyện/,'📖'],
  [/dialogue|conversation|hội thoại|hỏi đáp/,'💬'],
  [/matching|matcher|ghép|nối|kéo thả/,'🧩'],
  [/fill|sentence|viết|điền|sắp xếp/,'📝'],
  [/grammar|ngữ pháp/,'🔎'],
  [/semester|học kỳ|ôn tập|review/,'🧠'],
  [/exam|đề thi|test|kiểm tra/,'🏆'],
  [/level\s*1\b|cấp\s*1\b|dễ/,'🌱'],
  [/level\s*2\b|cấp\s*2\b|vừa/,'🌼'],
  [/level\s*3\b|cấp\s*3\b|khó/,'🌟'],
  [/level\s*4\b|cấp\s*4\b|nâng cao/,'🏆']
 ];
 for(const [pattern,icon] of icons)if(pattern.test(text))return icon;
 return ['📚','🧩','🎯','✏️','🌟','💡'][index%6];
}
function ta2DecorateMenuCard_(btn,index){
 if(!btn||btn.dataset.ta2MenuReady==='1'||btn.disabled)return;
 if(btn.closest('.col-span-full,[data-ta2-menu-skip]'))return;
 if(btn.classList.contains('ta2-hub-card')){
  // Existing cards already include the official large icon or a thumbnail.
  btn.dataset.ta2MenuReady='1';
  return;
 }
 const tone=ta2MenuTone_(btn,index);
 const iconText=ta2TakeMenuEmoji_(btn)||ta2MenuIconFor_(btn.textContent,index);
 btn.classList.add('ta2-hub-card','ta2-hub-card--'+tone,'ta2-unified-menu-card');
 btn.dataset.ta2MenuReady='1';
 const icon=document.createElement('span');
 icon.className='ta2-hub-icon';
 icon.setAttribute('aria-hidden','true');
 icon.textContent=iconText;
 btn.insertBefore(icon,btn.firstChild);
}
function ta2DecorateAllMenus_(){
 const list=document.getElementById('lecture-subtopics-list');
 if(list){
  const all=Array.from(list.querySelectorAll('button[onclick]'));
  all.forEach((btn,i)=>ta2DecorateMenuCard_(btn,i));
 }
}
const ta2MenuStyleObserver_=new MutationObserver(()=>ta2DecorateAllMenus_());
function ta2StartMenuStyleObserver_(){
 const list=document.getElementById('lecture-subtopics-list');
 if(list)ta2MenuStyleObserver_.observe(list,{childList:true,subtree:true});
 ta2DecorateAllMenus_();
}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',ta2StartMenuStyleObserver_,{once:true});
else ta2StartMenuStyleObserver_();

const class2OriginalNav=updateNavTabs;
updateNavTabs=function(title,icon,a,b,handler){
 class2OriginalNav(title,icon,a,b,handler);
 if(!taModuleCtx_)return;
 if(!title){taModuleCtx_?.hooks?.setDetail(null);return;}
 const levels=[2,3,4,5];
 const items=levels.map(level=>{
  const wrap=document.getElementById(`header-level${level}-tab`);
  const button=document.getElementById(`header-level${level}-btn`);
  const label=document.getElementById(`header-level${level}-title`);
  if(!wrap||wrap.classList.contains('hidden')||!button||!label)return null;
  const name=String(label.textContent||'').trim();
  if(!name)return null;
  const canGo=button.hasAttribute('data-navigate');
  return {title:name,level,action:canGo?()=>{
   if(!class2Active||!button.isConnected)return;
   button.click();
  }:null};
 }).filter(Boolean);
 if(taModuleCtx_?.hooks?.supportsStructuredDetail === true){
  taModuleCtx_?.hooks?.setDetail({title:items.map(item=>item.title).join(' › '),items});
 }else{
  // Module cũ hoặc shell còn nằm trong cache: không gửi object vào API chỉ nhận string.
  taModuleCtx_?.hooks?.setDetail([title,a,b].filter(Boolean).join(' › '));
 }
};

  
// Presentation-only placement of the question voice button on narrow screens.
(function () {
    const homes = new Map();
    let pending = 0;
    function update() {
        const box = document.getElementById('question-box');
        if (!box) return;
        const mobile = window.matchMedia('(max-width:767px)').matches;
        for (const [button,marker] of homes) {
            if (!button.isConnected && !marker.isConnected) { homes.delete(button); continue; }
            if (!mobile && marker.isConnected) marker.replaceWith(button);
            if (!mobile) homes.delete(button);
        }
        let row = box.querySelector(':scope > .ta2-mobile-listen-row');
        if (!mobile) { row?.remove(); return; }
        const buttons = Array.from(box.querySelectorAll('button[onclick*="speakCurrentQuestion"]'));
        if (!buttons.length) { row?.remove(); return; }
        if (!row) { row=document.createElement('div');row.className='ta2-mobile-listen-row';box.prepend(row); }
        for (const button of buttons) {
            if (button.parentElement===row) continue;
            const marker=document.createComment('ta-question-audio-place');
            button.before(marker);homes.set(button,marker);row.append(button);
        }
    }
    function schedule() {
        if(pending) cancelAnimationFrame(pending);
        pending=requestAnimationFrame(()=>{pending=0;update();});
    }
    function setup() {
        const box=document.getElementById('question-box');
        if (!box)return;
        new MutationObserver(schedule).observe(box,{childList:true,subtree:true});
        window.addEventListener('resize',schedule);
        schedule();
    }
    if (document.readyState==='loading') document.addEventListener('DOMContentLoaded',setup,{once:true});
    else setup();
})();

  
