  "startAdvancedSituationReadingLevel_":(typeof startAdvancedSituationReadingLevel_ === 'function' ? startAdvancedSituationReadingLevel_:null),
  "startExamCountdown":(typeof startExamCountdown === 'function' ? startExamCountdown:null),
  "startPictureQuestionReviewLevel_":(typeof startPictureQuestionReviewLevel_ === 'function' ? startPictureQuestionReviewLevel_:null),
  "startRandomExam":(typeof startRandomExam === 'function' ? startRandomExam:null),
