  "startTopicQuiz":(typeof startTopicQuiz === 'function' ? startTopicQuiz:null),
  "startVocabularyMode18":(typeof startVocabularyMode18 === 'function' ? startVocabularyMode18:null),
  "switchAppView":(typeof switchAppView === 'function' ? switchAppView:null),
