  "ta2StartSpeechRecognition_":(typeof ta2StartSpeechRecognition_ === 'function' ? ta2StartSpeechRecognition_:null),
  "toggleAdvancedVocabularySelection_":(typeof toggleAdvancedVocabularySelection_ === 'function' ? toggleAdvancedVocabularySelection_:null),
  "toggleAutoSpeech":(typeof toggleAutoSpeech === 'function' ? toggleAutoSpeech:null),
  "toggleFlashcardVietnamese":(typeof toggleFlashcardVietnamese === 'function' ? toggleFlashcardVietnamese:null),
  "toggleRemoveLetterToken_":(typeof toggleRemoveLetterToken_ === 'function' ? toggleRemoveLetterToken_:null),
